import {FISCAL_LATEST as refs} from './fiscal-latest-data.mjs';
import {TARIFF_DATA} from './tariff-data.mjs';
import {REVISION130 as audit} from './revision130-data.mjs';
const n=(x,d=2)=>Number.isFinite(x)?x.toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d}):'Unavailable';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>Number.isFinite(x)?n(x)+'%':'Unavailable';
export function calendarLabel(row){return `Year ${row.t} · ${row.calendarYear??2023+row.t}`;}
export function latestFiscalHTML(code){
 const c=refs[code];if(!c)return '';
 const x=c.latest;
 return `<details class="public-budget-reference" open><summary>Latest observed fiscal reference · ${esc(c.name)} · ${x.year}</summary><table><caption>Observed data, separate from the simulation · % nominal GDP</caption><tbody>${[['Opening deficit · 2023',c.openingDeficitGDP],['Latest deficit (negative = surplus) · '+x.year,x.deficitGDP],['Latest total revenue',x.revenueGDP],['Latest total expenditure',x.expenditureGDP],['Latest public debt',x.debtGDP]].map(([label,value])=>`<tr><th scope="row">${label}</th><td>${pct(value)}</td></tr>`).join('')}</tbody></table><p class="small muted">${esc(x.scope)}. ${esc(x.note)} Opening year 0 remains 2023 so that stocks, trade, employment and fiscal data refer to the same starting year. Later simulated deficits are outcomes, not observed targets. References verified as of 20 November 2026.</p><a href="${esc(x.sourceURL)}" target="_blank" rel="noreferrer">Official fiscal reference</a></details>`;
}
export function debtBridgeHTML(r){
 if(!r.publicDebtBridgeDefined)return '<p class="small muted">The public-debt change starts after the opening observation and requires positive nominal GDP in both years.</p>';
 const rows=[['Deficit / current nominal GDP',r.publicDebtDeficitContribution],['Other financial transactions / current GDP',r.publicDebtOtherFlowsContribution],['Change in the nominal GDP denominator',r.publicDebtGDPContribution]];
 const cash=[['Total deficit · positive raises debt',r.publicDeficit],['Change in treasury cash',r.publicDebtCashAdjustment],['Financial-sector recapitalisation',r.publicDebtRecapitalizationAdjustment],['Proceeds from public equity liquidation',r.publicDebtLiquidationAdjustment],['Noncash pension interest accrued',r.publicDebtNoncashPensionAdjustment]];
 return `<details class="public-budget-reference"><summary>Why public debt / GDP changed in ${r.calendarYear}</summary><table><caption>Exact change in public debt / GDP · percentage points</caption><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th><td>${n(value)}</td></tr>`).join('')}</tbody><tfoot><tr><th>Total change</th><td>${n(r.publicDebtRatioChange)}</td></tr></tfoot></table><table><caption>Change in the outstanding debt stock · nominal model units</caption><tbody>${cash.map(([label,value])=>`<tr><th scope="row">${label}</th><td>${n(value)}</td></tr>`).join('')}</tbody><tfoot><tr><th>Total change in debt</th><td>${n(r.publicDebtStockChange)}</td></tr></tfoot></table><p class="small muted">A smaller deficit slows new borrowing. Debt / GDP can still rise when there is a deficit, weak nominal GDP or other financing needs. Cash holdings and noncash accruals explain why debt need not change by exactly the deficit. Principal repaid is financing, not another expense.</p></details>`;
}
export function tariffReferenceHTML(code){
 const t=TARIFF_DATA[code];if(!t)return '';
 const member=!['USA','CHN','EU27'].includes(code);
 return `<p><strong>Opening effective goods tariff: ${n(t.effectiveTariffPercent,3)}% · 2023.</strong> Observed customs duties (${n(t.dutiesMillion,0)} million ${esc(t.currency)}) divided by matched goods imports (${n(t.goodsImportsMillion,0)} million ${esc(t.currency)}). ${esc(t.importScope)}. This measures the average duty paid; individual statutory rates differ. ${member?'Customs duties belong to EU institutions. The national collector retains 25% as collection compensation; the model settles the net 75% externally.':(code==='EU27'?'Duties remain within the EU27 economy, including EU institutions.':'Duties remain within this modeled economy.')} The goods-only estimate is mapped to the model’s composite import good; it is not a tariff on services or a 2026 policy forecast.</p><p><a href="${esc(t.dutySource)}" target="_blank" rel="noreferrer">Customs-duty source</a> · <a href="${esc(t.importSource)}" target="_blank" rel="noreferrer">Goods-import source</a></p>`;
}
export function revision130HTML(code){
 const c=audit.byCountry[code],s=audit.scoreCountries;
 return `<section class="panel content-panel" id="tariff-fiscal-evidence"><div class="eyebrow">TARIFF AND FISCAL AUDIT · ENGINE 1.30</div><h2>Observed tariffs and dated public budgets</h2>${tariffReferenceHTML(code)}${latestFiscalHTML(code)}<p><strong>Exceptional opening spending is no longer repeated forever.</strong> Where a current/capital split is available, capital fiscal spending and receipts use their published 2024 and 2025 shares, applied to the model’s budget base. Later years hold the last available shares as an assumption. The current budget remains simulated. China’s missing split remains unavailable rather than being invented.</p><p>This is a conditional historical simulation: it incorporates capital-budget information published after 2023. It is not a forecast made in 2023, and it does not force deficits to match a target. Italy’s 2023 payable tax credits also create later cash/debt effects that need an opening credit-liability stock and redemption schedule; those could not be verified here. The model’s cash-transfer capital bridge does not reproduce that full accrual-to-cash schedule.</p><details><summary>Executed checks and remaining errors</summary><p>${audit.paths} paths and ${audit.annualSteps.toLocaleString()} annual steps cover all 30 presets. Opening import border values and current accounts are preserved. GDP, saving less investment, changes in net foreign assets, public/private debt and the customs settlement reconcile. Largest relative sector-account residual: ${audit.maxResidual.toExponential(2)}; public-debt bridge residual relative to debt scale: ${audit.maxRelativePublicDebtBridge.toExponential(2)}. ${audit.legacyValues.toLocaleString()} common values reproduce the frozen 1.29 model with the additions disabled.</p><p>For ${esc(c.name)}, mean simulated ${c.latestYear} deficit is ${pct(c.modelDeficitGDP)}, versus the same-scope observed ${pct(c.observedDeficitGDP)}. This difference remains visible. Across individual countries, conditional deficit RMSE changes from ${n(s.deficit.earlier.RMSE)} to ${n(s.deficit.candidate.RMSE)} percentage points; real-GDP growth RMSE changes from ${n(s.gdp.earlier.RMSE)} to ${n(s.gdp.candidate.RMSE)}. These comparisons use previously examined revised observations and future capital-budget information. They cannot establish improved forecasting accuracy. The EU aggregate is scored separately.</p><p>National EU tariffs include duty-free intra-EU goods, whereas the EU27 denominator excludes intra-EU trade. The different averages are intentional. Duties collected at a border need not identify the final resident importer, so national rates remain aggregate proxies. Collection compensation is a net settlement proxy, not a separately produced service in this model. The EU27 fiscal bridge does not include a full separate EU-institution budget. Trade elasticities and future fiscal, demographic and private behaviour remain assumptions.</p><div class="table-wrap"><table><caption>Every preset · effective 2023 tariff and latest fiscal comparison</caption><thead><tr><th>Economy</th><th>Tariff</th><th>Fiscal year</th><th>Observed deficit / GDP</th><th>Simulated mean</th></tr></thead><tbody>${Object.entries(audit.byCountry).sort((a,b)=>a[1].name.localeCompare(b[1].name)).map(([k,x])=>`<tr><th scope="row">${esc(x.name)}</th><td>${n(TARIFF_DATA[k].effectiveTariffPercent,3)}%</td><td>${x.latestYear}</td><td>${pct(x.observedDeficitGDP)}</td><td>${pct(x.modelDeficitGDP)}</td></tr>`).join('')}</tbody></table></div></details><p><a href="./data/revision130_validation.json" download>All simulation checks and comparisons</a> · <a href="./data/tariffs_2023.json" download>Tariff data and exact source definitions</a> · <a href="./data/latest_fiscal_references.json" download>Latest fiscal observations</a></p></section>`;
}
